    gpio_set_function(SCL_PIN, GPIO_FUNC_I2C);
    gpio_pull_up(SDA_PIN);
    gpio_pull_up(SCL_PIN);

    // Perform aligned I2C bus scan
    i2c_scan();

    // Configure LM75B sensor & Apply defined thresholds
    configure_lm75b();
    set_temp_threshold(REG_TOS, TOS_TEMP);   
    set_temp_threshold(REG_THYST, THYST_TEMP); 

    // Initialize LED pin (GP15)
    gpio_init(LED_PIN);
    gpio_set_dir(LED_PIN, GPIO_OUT);
    gpio_put(LED_PIN, 1);

    // Initialize OS Sensor Interrupt Pin (GP16)
    gpio_init(OS_INT_PIN);
    gpio_set_dir(OS_INT_PIN, GPIO_IN);
    gpio_pull_up(OS_INT_PIN);

    gpio_set_irq_enabled_with_callback(OS_INT_PIN, GPIO_IRQ_EDGE_RISE | GPIO_IRQ_EDGE_FALL, true, &gpio_callback);

    printf("LM75B Running.\n");
    printf("SDA pin: %d | SCL pin: %d | OS pin: %d \n", 
           SDA_PIN, SCL_PIN, OS_INT_PIN);
    printf("TOS Limit: %.1f C | THYST Limit: %.1f C | Alarm LED Pin: GP%d\n\n", 
           TOS_TEMP, THYST_TEMP, LED_PIN);

    printf("Measurements start in 1 sec.\n\n"); 
    sleep_ms(1000); // Give serial monitor time to connect
    gpio_put(LED_PIN, 0);


    // Main Loop
    while (true) {
        float temp = read_temperature();
        printf("Current Temperature: %.2f C\n", temp);
        sleep_ms(1000);
    }

    return 0;
}


